[CmdletBinding()]param()
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;Push-Location $root;try{python -m unittest scripts.tests.test_local_snapshot_release_policy;if($LASTEXITCODE){exit $LASTEXITCODE};cargo test --manifest-path sdk/tools/release-freeze-validator/Cargo.toml --locked --offline;if($LASTEXITCODE){exit $LASTEXITCODE};$rev=(&git rev-parse HEAD).Trim()}finally{Pop-Location}
$base=Join-Path $root 'target/openspec-evidence/build-extensible-plugin-platform';1..6|%{$id="2.4.$_";$dir=Join-Path $base $id;New-Item -ItemType Directory -Force $dir|Out-Null;$report=[ordered]@{schema_version=1;task_id=$id;procedure_kind='command';command='powershell -NoProfile -ExecutionPolicy Bypass -File scripts/run_local_snapshot_release_contract.ps1';cwd='.';environment=[ordered]@{validation_authority='local-only';uitest_executed='false';offline='true'};expected='exit code 0';actual='passed';exit_code=0;source_revision=$rev;input_sha256=[ordered]@{}};foreach($path in @('scripts/tests/test_local_snapshot_release_policy.py','sdk/scripts/update-gpui-snapshot.ps1','sdk/scripts/freeze-release.ps1','sdk/schemas/release-freeze.schema.json')){$report.input_sha256[$path]=(Get-FileHash -LiteralPath (Join-Path $root $path) -Algorithm SHA256).Hash.ToLowerInvariant()};$out=Join-Path $dir 'result.json';[IO.File]::WriteAllText($out,(($report|ConvertTo-Json -Depth 5)+[Environment]::NewLine),[Text.UTF8Encoding]::new($false));Write-Output "REPORT $id $((Get-FileHash -LiteralPath $out -Algorithm SHA256).Hash.ToLowerInvariant())"}
